const http = require('http');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

const readFile = promisify(fs.readFile);
const stat = promisify(fs.stat);

const STORAGE_ROOT = '/var/app/secure_storage';
const MAX_CHUNK_SIZE = 4096;
const HMAC_KEY = crypto.randomBytes(32);

// Session store with expiry
const sessions = new Map();

function createSession(userId) {
  const token = crypto.randomBytes(24).toString('hex');
  sessions.set(token, { userId, created: Date.now(), expires: Date.now() + 3600000 });
  return token;
}

function verifySession(token) {
  if (!token || typeof token !== 'string') return null;
  const session = sessions.get(token);
  if (!session) return null;
  if (Date.now() > session.expires) {
    sessions.delete(token);
    return null;
  }
  return session;
}

// Compute HMAC for integrity verification
function computeHMAC(data) {
  return crypto.createHmac('sha256', HMAC_KEY).update(data).digest('hex');
}

// Validate and parse the request envelope
function parseRequestEnvelope(body) {
  try {
    const envelope = JSON.parse(body);
    if (!envelope || typeof envelope !== 'object') return null;

    const { resource, offset, length, signature } = envelope;

    // Verify request integrity
    const payload = JSON.stringify({ resource, offset, length });
    const expectedSig = computeHMAC(payload);
    if (!signature || !crypto.timingSafeEqual(
      Buffer.from(signature, 'hex'),
      Buffer.from(expectedSig, 'hex')
    )) {
      return null;
    }

    return { resource, offset, length };
  } catch (e) {
    return null;
  }
}

// Sanitize resource path - thorough validation
function sanitizeResource(resource) {
  if (typeof resource !== 'string') return null;
  if (resource.length === 0 || resource.length > 200) return null;

  // Reject null bytes
  if (resource.indexOf('\x00') !== -1) return null;

  // Normalize unicode
  const normalized = resource.normalize('NFC');

  // Reject path separators and traversal
  if (normalized.includes('..')) return null;
  if (normalized.includes('/')) return null;
  if (normalized.includes('\\')) return null;

  // Strict allowlist: alphanumeric, dot, hyphen, underscore
  if (!/^[a-zA-Z0-9][a-zA-Z0-9._-]*$/.test(normalized)) return null;

  // Must have valid extension
  const ext = path.extname(normalized).toLowerCase();
  if (!['.txt', '.json', '.xml', '.csv', '.log'].includes(ext)) return null;

  return normalized;
}

// Validate numeric range parameters
function validateRange(offset, length) {
  // Parse as integers
  const parsedOffset = parseInt(offset, 10);
  const parsedLength = parseInt(length, 10);

  // Boundary validation - ensure within acceptable range
  if (parsedOffset < 0) return null;
  if (parsedLength < 1) return null;
  if (parsedLength > MAX_CHUNK_SIZE) return null;

  // Overflow check: ensure offset + length doesn't wrap
  if (parsedOffset + parsedLength < parsedOffset) return null;

  return { offset: parsedOffset, length: parsedLength };
}

// Build safe file path with containment
function buildFilePath(resource) {
  const fullPath = path.resolve(STORAGE_ROOT, resource);

  // Containment check
  if (!fullPath.startsWith(STORAGE_ROOT + path.sep)) return null;

  return fullPath;
}

// Read a chunk from file
async function readChunk(filePath, offset, length) {
  const fileHandle = await fs.promises.open(filePath, 'r');
  try {
    const buffer = Buffer.alloc(length);
    const { bytesRead } = await fileHandle.read(buffer, 0, length, offset);
    return buffer.slice(0, bytesRead);
  } finally {
    await fileHandle.close();
  }
}

const server = http.createServer(async (req, res) => {
  res.setHeader('Content-Type', 'application/json');

  if (req.method === 'POST' && req.url === '/api/auth') {
    let body = '';
    req.on('data', c => { body += c; if (body.length > 1024) req.destroy(); });
    req.on('end', () => {
      try {
        const { username } = JSON.parse(body);
        if (typeof username === 'string' && username.length > 0 && username.length < 64) {
          const token = createSession(username);
          res.writeHead(200);
          res.end(JSON.stringify({ token, hmacKey: HMAC_KEY.toString('hex') }));
        } else {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid username' }));
        }
      } catch (e) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Bad request' }));
      }
    });
    return;
  }

  if (req.method === 'POST' && req.url === '/api/read') {
    const token = req.headers['x-auth-token'];
    const session = verifySession(token);
    if (!session) {
      res.writeHead(401);
      res.end(JSON.stringify({ error: 'Unauthorized' }));
      return;
    }

    let body = '';
    req.on('data', c => { body += c; if (body.length > 4096) req.destroy(); });
    req.on('end', async () => {
      try {
        const envelope = parseRequestEnvelope(body);
        if (!envelope) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid request envelope' }));
          return;
        }

        const { resource, offset, length } = envelope;

        // Validate resource name
        const safeName = sanitizeResource(resource);
        if (!safeName) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid resource name' }));
          return;
        }

        // Validate range parameters
        const range = validateRange(offset, length);
        if (!range) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid range' }));
          return;
        }

        // Build safe path
        const filePath = buildFilePath(safeName);
        if (!filePath) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Path resolution failed' }));
          return;
        }

        // Read the chunk
        const data = await readChunk(filePath, range.offset, range.length);

        res.writeHead(200);
        res.end(JSON.stringify({
          resource: safeName,
          offset: range.offset,
          bytesRead: data.length,
          data: data.toString('base64')
        }));
      } catch (e) {
        if (e.code === 'ENOENT') {
          res.writeHead(404);
          res.end(JSON.stringify({ error: 'Resource not found' }));
        } else {
          res.writeHead(500);
          res.end(JSON.stringify({ error: 'Internal error' }));
        }
      }
    });
    return;
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(3000);
